# Each: id, lesson, pattern, meaning, form, notes, ex[(jp,en)], q=(sentence with ＿＿, options, answerIndex, explanation)
G=[
(1,1,"V(stem) ながら","while doing (two actions at once)","Verb stem + ながら; the main action comes last.","The subject of both actions must be the same.",[("おんがくを ききながら べんきょうします。","I study while listening to music."),("あるきながら でんわを しないでください。","Please don't talk on the phone while walking.")],("コーヒーを ＿＿ しんぶんを よみます。",["のむながら","のみながら","のんながら","のんで"],1,"ながら attaches to the verb stem (masu-form without ます): のみ + ながら.")),
(2,1,"V(た) ことがある","have done (experience)","Plain past (た-form) + ことがある","Talks about past experiences, not a specific time. Negative: ～たことがない.",[("ふじさんに のぼったことが あります。","I have climbed Mt. Fuji."),("すしを たべたことが ありません。","I have never eaten sushi.")],("にほんへ ＿＿ ことが ありますか。",["いく","いって","いった","いきます"],2,"Experience uses the plain past (た-form): いった + ことがある.")),
(3,2,"V(dict./ない) ことがある","sometimes does","Plain present + ことがある","Describes things that happen occasionally.",[("あさ ごはんを たべないことが あります。","Sometimes I don't eat breakfast."),("ともだちと りょこうに いくことが あります。","I sometimes travel with friends.")],("いそがしいとき、ひるごはんを ＿＿ ことが あります。",["たべない","たべなかった","たべて","たべません"],0,"'Sometimes' uses the plain present: たべない + ことがある.")),
(4,2,"V(て) みる","try doing","て-form + みる","To do something to see how it is.",[("この くつを はいてみても いいですか。","May I try on these shoes?"),("あたらしい レストランに いってみました。","I tried going to the new restaurant.")],("この ケーキを ＿＿ みてください。",["たべて","たべる","たべた","たべに"],0,"'Try doing' = て-form + みる.")),
(5,3,"V(て) おく","do in advance, leave as is","て-form + おく","Preparing beforehand or leaving a state. Casual: ～ておく → ～とく.",[("りょこうの まえに ホテルを よやくしておきます。","I will book the hotel before the trip."),("まどを あけておいてください。","Please leave the window open.")],("パーティーの まえに ビールを ＿＿ おきます。",["かって","かう","かった","かいに"],0,"Doing in preparation = て-form + おく.")),
(6,3,"V(て) しまう","finish completely / regret","て-form + しまう","Completion, or something unfortunate. Casual: ～ちゃう / ～じゃう.",[("しゅくだいを ぜんぶ してしまいました。","I finished all my homework."),("かぎを なくしてしまいました。","I (regrettably) lost my key.")],("さいふを ＿＿ しまいました。",["わすれて","わすれる","わすれた","わすれに"],0,"て-form + しまう expresses regret or completion.")),
(7,4,"V(て) ある","state resulting from someone's action","Transitive verb て-form + ある","Describes a state that someone caused on purpose. Particle が/は.",[("つくえの うえに ほんが おいてあります。","A book has been placed on the desk."),("かべに えが かけてあります。","A picture is hung on the wall.")],("ドアが ＿＿ あります。",["しめて","しまって","しめる","しまる"],0,"が + transitive verb て-form + ある: しめてある (someone closed it).")),
(8,4,"～そうだ (appearance)","looks like, seems about to","V(stem)/い-adj stem/な-adj + そうだ","Based on what you see. いい → よさそう, ない → なさそう.",[("あめが ふりそうです。","It looks like it will rain."),("この ケーキは おいしそうです。","This cake looks delicious.")],("この りょうりは ＿＿ そうです。",["から","からい","からく","からくて"],0,"Appearance そう attaches to the い-adjective stem (drop い): から + そう = looks spicy.")),
(9,5,"～そうだ (hearsay)","I heard that","Plain form + そうだ","Reports information from someone else; not based on your own impression.",[("てんきよほうに よると、あしたは あめだそうです。","According to the forecast, it will rain tomorrow."),("たなかさんは かぜだそうです。","I heard Mr. Tanaka has a cold.")],("ニュースに よると、きのう じしんが ＿＿ そうです。",["あった","ありそう","あれば","あって"],0,"Hearsay uses plain form + そうだ: あった + そうだ.")),
(10,5,"～かもしれない","might, may","Plain form (な-adj/noun without だ) + かもしれない","Possibility, less certain than でしょう.",[("あしたは ゆきが ふるかもしれません。","It might snow tomorrow."),("かれは びょうきかもしれません。","He might be ill.")],("かぎは かばんの なかに ＿＿ かもしれません。",["ある","あります","あって","あれば"],0,"かもしれない follows the plain form: ある + かもしれない.")),
(11,6,"～でしょう / だろう","probably","Plain form + でしょう","Speaker's guess; rising intonation asks for agreement.",[("あしたは はれるでしょう。","It will probably be sunny tomorrow."),("かれも くるでしょう。","He will probably come too.")],("もう すぐ バスが ＿＿ でしょう。",["くる","きて","きた","きます"],0,"Prediction about the future: plain present + でしょう.")),
(12,6,"～ので","because (objective reason)","Plain form (な-adj/noun + な) + ので","Softer and more polite than から; good for explaining.",[("あめが ふっているので、うちに います。","Since it's raining, I'm staying home."),("ねつが あるので、やすみます。","I have a fever, so I'll take the day off.")],("ひまな＿＿、さんぽに いきました。",["ので","ながら","ように","けれど"],0,"な-adjective + な + ので = because. (ひまなけれど / ひまなながら are not possible.)")),
(13,7,"～のに","although, despite","Plain form (な-adj/noun + な) + のに","Expresses unexpected results or complaint.",[("くすりを のんだのに、まだ ねつが あります。","Even though I took medicine, I still have a fever."),("やすみなのに、しごとを します。","Even though it's a holiday, I work.")],("べんきょうした＿＿、テストが わるかった。",["のに","ので","から","ために"],0,"Unexpected result = のに (although).")),
(14,7,"～ば (conditional)","if ... (general condition)","V(e-form + ば) / い-adj ければ","Condition and natural result; also advice: ～ば いい.",[("いそげば、まにあいます。","If you hurry, you'll be in time."),("やすければ、かいます。","If it's cheap, I'll buy it.")],("よく ＿＿ ば、ごうかくできます。",["べんきょうすれ","べんきょうする","べんきょうして","べんきょうした"],0,"する → すれば. Verb conditional ～ば: べんきょうすれ + ば.")),
(15,8,"～たら (conditional)","if / when ...","Plain past + ら","Broad condition; after-the-fact discovery; 'when' for future events.",[("あめが ふったら、いきません。","If it rains, I won't go."),("うちに かえったら、でんわします。","When I get home, I'll call.")],("おかねが ＿＿ ら、りょこうに いきたいです。",["あった","あれ","ある","あって"],0,"たら = plain past + ら: あった + ら.")),
(16,8,"～なら","if (it's the case that)","Plain form + なら","Respond to a topic someone has just raised; advice.",[("にほんへ いくなら、きょうとが おすすめです。","If you're going to Japan, I recommend Kyoto."),("やすいなら、かいます。","If it's cheap, I'll buy it.")],("A: あした こうえんへ いきます。 B: こうえんへ ＿＿ なら、おべんとうを もっていきましょう。",["いく","いった","いって","いけば"],0,"Following the other person's topic: plain present + なら.")),
(17,9,"V(stem) すぎる","too much, excessively","Verb stem / い-adj stem / な-adj + すぎる","Usually negative nuance.",[("きのう たべすぎました。","I ate too much yesterday."),("この かばんは たかすぎます。","This bag is too expensive.")],("この へやは あつ＿＿ ます。",["すぎ","すぎる","そう","らしい"],0,"い-adj stem (あつ) + すぎる; with ます it becomes すぎ + ます.")),
(18,9,"V(stem) やすい / にくい","easy to / hard to","Verb stem + やすい / にくい","Describes how easy or difficult an action is.",[("この ペンは かきやすいです。","This pen is easy to write with."),("この くつは あるきにくいです。","These shoes are hard to walk in.")],("この じしょは ＿＿ やすいです。",["つかい","つかう","つかって","つかった"],0,"Verb stem + やすい: つかい + やすい.")),
(19,10,"V(て) あげる/もらう/くれる","give / receive / receive from (favors)","て-form + あげる/もらう/くれる","あげる: I do for you. もらう: I receive. くれる: someone does for me.",[("ともだちに ほんを かしてあげました。","I lent my friend a book (as a favor)."),("せんせいが しゃしんを とってくれました。","The teacher took a photo for me.")],("ともだちが にもつを ＿＿ くれました。",["もって","もつ","もった","もち"],0,"て-form + くれる: someone did something for me.")),
(20,10,"～(ら)れる (passive)","is done to someone","V(a-form + れる) / V(ない-stem + られる)","Subject is affected; often 'trouble passive'.",[("せんせいに ほめられました。","I was praised by the teacher."),("あめに ふられました。","I got rained on (and was inconvenienced).")],("かれは せんせいに ＿＿ 。",["しかられました","しかりました","しかって","しかる"],0,"Passive: しかる → しかられる. 'He was scolded by the teacher.'")),
(21,11,"～させる (causative)","make/let someone do","V(a-form + せる) / V(ない-stem + させる)","Cause or permit someone's action.",[("はは は こどもに やさいを たべさせます。","Mother makes the child eat vegetables."),("せんせいは がくせいに ほんを よませました。","The teacher had the students read the book.")],("しゃちょうは しゃいんに ざんぎょうを ＿＿ 。",["させました","しました","されました","して"],0,"Causative of する is させる: the president made the employee work overtime.")),
(22,11,"～ようだ / みたいだ","seems, looks like","Plain form + ようだ / みたいだ","Judgment from evidence you observed or experienced.",[("かれは つかれているようです。","He seems tired."),("あめが ふったようです。","It looks like it rained.")],("へやの でんきが ついているから、だれかが いる＿＿ です。",["よう","ため","ところ","ばかり"],0,"Inference from evidence you can see: plain form + ようだ (いる + ようです).")),
(23,12,"～はずだ","should be, expected to","Plain form (な-adj + な / noun + の) + はずだ","Speaker's strong expectation based on reasoning.",[("かれは もう ついているはずです。","He should have arrived already."),("この ほんは おもしろいはずです。","This book should be interesting.")],("でんしゃは 九じに ＿＿ はずです。",["つく","つき","ついた","ついて"],0,"Expectation about the future: plain present + はずだ.")),
(24,12,"～ことにする / ～ことになる","decide to / it has been decided that","V(dict./ない) + ことにする / ことになる","することにする: your own decision. することになる: decided by others or by circumstances.",[("らいねん にほんに りゅうがくすることにしました。","I decided to study in Japan next year."),("らいげつ とうきょうへ いくことになりました。","It has been decided that I'll go to Tokyo next month.")],("かいしゃの きまりで、らいしゅうから わたしは おおさかで はたらく＿＿ なりました。",["ことに","ことを","ので","ばかり"],0,"A decision made by the company: ことに + なりました (it has been decided).")),
]
